            new TaskId("node", randomNonNegativeLong()),
            randomBoolean(),
            randomBoolean() ? null : TimeValue.timeValueSeconds(randomIntBetween(1, 60))
        );
        assertThat(request.validate(), is(nullValue()));
    }
}

